function material(color,roughness=.85,metalness=.08){const m=new T.MeshStandardMaterial({color,roughness,metalness});m.userData.owned=true;return m;}
const mats={dark:material('#252e2a'),steel:material('#4d5c55',.5,.55),black:material('#1a2220'),boot:material('#242b27'),skin:material('#9b886d'),glass:material('#1c3b39',.2,.5),sandbag:material('#8c8b6c'),wood:material('#6b7560'),coreBlue:material('#9bdad0',.3,.45),coreRed:material('#d68468',.3,.4)};
