function noiseTexture(base){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=base;ctx.fillRect(0,0,256,256);let seed=713;const rng=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};for(let i=0;i<12000;i++){const q=Math.floor(rng()*255);ctx.fillStyle=`rgba(${q},${q},${q},${.03+rng()*.14})`;const s=.3+rng()*2;ctx.fillRect(rng()*256,rng()*256,s,s);}const t=new T.CanvasTexture(c);t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(36,50);t.colorSpace=T.SRGBColorSpace;return t;}
function camoTexture(color){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');ctx.fillStyle=color;ctx.fillRect(0,0,128,128);for(let i=0;i<65;i++){ctx.fillStyle=['#334538','#9c9b71','#596749','#283b32'][i%4];ctx.fillRect((i*37)%128,(i*61)%128,8+(i%4)*4,5+(i%6)*3);}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t;}
const camoMat=new T.MeshStandardMaterial({map:camoTexture(skins[state.skin].color),roughness:1});camoMat.userData.softwareColor=skins[state.skin].color;
function disposeGroup(group){const materials=new Set();group.traverse(o=>{if(o.isMesh){o.geometry.dispose();if(o.userData.disposableMaterial||o.material.userData.owned&&!o.material.userData.shared)materials.add(o.material);}});for(const m of materials){m.map?.dispose();m.dispose();}group.clear();}
function obstacle(x,z,w,d,h,mat){const mesh=box(world,w,h,d,x,h/2,z,mat);obstacles.push({x,z,w:w/2,d:d/2});coverMeshes.push(mesh);return mesh;}
function sandbags(x,z,width=7,rotation=0){const group=new T.Group();world.add(group);group.position.set(x,0,z);group.rotation.y=rotation;for(let row=0;row<3;row++)for(let i=0;i<5;i++){const b=box(group,width/5*.98,.34,.85,-width/2+width/10+i*width/5+(row%2)*.13,.2+row*.3,0,mats.sandbag);b.rotation.y=(i%3-1)*.025;coverMeshes.push(b);}const w=rotation?1:width,d=rotation?width:1;obstacles.push({x,z,w:w/2+.15,d:d/2+.15});}
function buildWorld(){disposeGroup(world);obstacles=[];coverMeshes=[];const th=theme();scene.background.set(th.sky);scene.fog.color.set(th.sky);const gm=new T.MeshStandardMaterial({map:noiseTexture(th.ground),roughness:1});const ground=new T.Mesh(new T.PlaneGeometry(230,280),gm);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;ground.userData.disposableMaterial=true;world.add(ground);const roadMat=material('#69746b');box(world,14,.025,138,0,.01,0,roadMat,false);
for(let i=0;i<14;i++)box(world,.16,.035,3,0,.04,-63+i*10,material('#b1ad8b'),false);
const wm=material(th.wall);for(const sign of [-1,1]){obstacle(sign*49,0,2,140,5,wm);for(let i=0;i<6;i++){const z=-58+i*23;obstacle(sign*35,z,12,13,5+(i%3)*2,wm);box(world,12.6,.3,13.6,sign*35,5+(i%3)*2,z,mats.dark);for(let j=0;j<3;j++)box(world,.05,1.4,1.5,sign*28.95,2.9,z-4+j*3,mats.glass);for(let j=0;j<4;j++){const x=sign*(55+j*13);cylinder(world,.2,.4,12+(j%3)*4,x,5+j%3*2,z,mats.wood,6);if(th.sub!=='城市战区')for(let k=0;k<3;k++){const leaf=new T.Mesh(new T.ConeGeometry(3.2-k*.55,5.5,7),material(th.leaf));leaf.position.set(x,9+k*2,z);world.add(leaf);}}}}
for(const [x,z,r] of [[-13,30,0],[16,22,0],[-15,3,0],[12,-9,0],[-16,-28,0],[17,-38,0],[-23,45,Math.PI/2],[23,-48,Math.PI/2]])sandbags(x,z,8,r);
for(let i=0;i<15;i++){const x=(i%2?1:-1)*(20+(i%4)*1.4),z=-45+(i*17)%90;obstacle(x,z,2.7,2.6,2.7,mats.wood);box(world,2.8,.12,2.7,x,2.1,z,mats.dark);box(world,.12,2.7,2.8,x,1.35,z,mats.dark);}
for(const x of [-24,24])for(const z of [-57,57]){for(const xx of [-1,1])for(const zz of [-1,1])box(world,.16,6,.16,x+xx*1.5,3,z+zz*1.5,mats.steel);box(world,4,.25,4,x,6,z,mats.wood);box(world,4.7,.3,4.7,x,8.6,z,mats.dark);for(let i=0;i<4;i++)box(world,.2,1,.2,x-1.7+i*1.1,6.6,z-1.8,mats.steel);const lamp=new T.Mesh(new T.ConeGeometry(1.4,4,4),mats.dark);lamp.rotation.y=Math.PI/4;lamp.scale.y=.3;lamp.position.set(x,9.3,z);world.add(lamp);}
for(let i=0;i<16;i++){const mountain=new T.Mesh(new T.ConeGeometry(19+(i%3)*5,20+(i%4)*9,5),material('#6e8379'));const a=i/16*Math.PI*2;mountain.position.set(Math.cos(a)*130,mountain.geometry.parameters.height/2-.1,Math.sin(a)*135);world.add(mountain);}
for(const z of [-60,60]){const sign=z>0?1:-1;const pad=cylinder(world,6,6,.22,0,.11,z,material(sign>0?'#5c7e70':'#8a7461'),32);pad.receiveShadow=true;box(world,9,.18,4,0,.1,z+sign*5,wm);}
}
function gunModel(level,firstPerson=false){const g=new T.Group(),info=weaponInfo('gun',level);const body=material(info.color,.5,.5),black=mats.black;const length=(level<10?.85:level<40?1.2:level<100?1.55:level<420?2:1.5)*(1+((level-1)%10)*.025);body.color.offsetHSL(((level-1)%9)*.003,0,((level-1)%7)*.012);box(g,.19,.23,length*.55,0,0,-length*.23,body);box(g,.13,.38,.15,0,-.22,0,black).rotation.x=-.25;box(g,.13,.32,.17,0,-.2,-.28,black).rotation.x=.15;const barrel=cylinder(g,.045,.05,length*.5,0,.025,-length*.72,black,10);barrel.rotation.x=Math.PI/2;box(g,.18,.14,.27,0,.06,.22,body);if(level>=10)box(g,.14,.2,.4,0,-.015,.47,black);if(level>=100&&level<420){const scope=cylinder(g,.075,.075,.45,0,.21,-.2,black);scope.rotation.x=Math.PI/2;cylinder(g,.1,.1,.05,0,.26,-.23,body).rotation.x=Math.PI/2;}if(level>=420){const em=new T.MeshStandardMaterial({color:'#83e8c4',emissive:'#54cbb2',emissiveIntensity:2});em.userData.owned=true;box(g,.2,.035,.6,0,.13,-.25,em);box(g,.25,.04,.18,0,.02,-1.0,em);}if(firstPerson){box(g,.14,.17,.5,.15,-.2,.3,camoMat).rotation.x=-.15;box(g,.14,.13,.35,-.13,-.18,-.08,camoMat).rotation.x=-.5;sphere(g,.09,.03,-.13,-.1,mats.skin);}return g;}
function knifeModel(level,firstPerson=false){const g=new T.Group();box(g,.1,.12,.36,0,0,.1,mats.black);box(g,.24+(level%5)*.02,.055,.07,0,0,-.1,mats.steel);const blade=box(g,.12,.035,.58+(level%10)*.015,0,0,-.44,material(level>=300?'#79d6c7':'#d2ded4',.25,.8));blade.rotation.z=.05;if(firstPerson){sphere(g,.095,.02,-.07,.16,mats.skin);box(g,.18,.16,.46,.08,-.12,.46,camoMat);}return g;}
function soldier(team,level=1){const group=new T.Group(),cloth=team==='ally'?camoMat:material('#81755e');const legL=box(group,.22,.75,.25,-.16,.49,0,cloth),legR=box(group,.22,.75,.25,.16,.49,0,cloth);box(group,.25,.17,.4,-.16,.11,-.07,mats.boot);box(group,.25,.17,.4,.16,.11,-.07,mats.boot);box(group,.64,.68,.34,0,1.14,0,cloth);box(group,.52,.5,.12,0,1.17,-.22,mats.dark);for(let i=0;i<3;i++)box(group,.13,.2,.1,-.17+i*.17,1.04,-.31,cloth);cylinder(group,.095,.1,.13,0,1.57,0,mats.skin);sphere(group,.205,0,1.81,0,mats.skin);const helmet=sphere(group,.232,0,1.91,.005,cloth);helmet.scale.y=.65;box(group,.36,.08,.13,0,1.83,-.19,mats.dark);box(group,.15,.5,.19,-.38,1.12,-.13,cloth).rotation.x=-.85;box(group,.15,.5,.19,.38,1.12,-.13,cloth).rotation.x=-.6;const gun=gunModel(level);gun.scale.setScalar(.75);gun.position.set(.18,1.18,-.37);group.add(gun);const badge=box(group,.12,.07,.05,-.34,1.35,-.03,material(team==='ally'?'#bfe68f':'#d97d5d'));const hit=[];group.traverse(o=>{if(o.isMesh)hit.push(o);});return {group,legL,legR,hit,weapon:gun,team,phase:Math.random()*6,hp:80,dead:false,respawn:0,cooldown:Math.random(),speed:2.8+Math.random()*.9};}
function makeCore(team,level,stage){const hps=team==='ally'?[600,240,700].map(n=>n*(1+(stage-1)*.035)*(1+(level-1)*.22)):[130,65,230].map(n=>n*(1+(stage-1)*.055));const c={team,level,hps,layer:0,hp:hps[0],max:hps[0],dead:false,group:new T.Group(),cooldown:0};c.group.position.set(0,0,team==='ally'?55:-55);actors.add(c.group);drawCore(c);return c;}
function drawCore(c){disposeGroup(c.group);if(c.dead){const rubble=material('#4a4b40');for(let i=0;i<9;i++){const m=box(c.group,.7,.3,.6,Math.sin(i*4)*2,.2,Math.cos(i*3)*2,rubble);m.rotation.set(.2,i,.3);}return;}
const color=c.team==='ally'?'#bde597':'#f4a37f',metal=c.team==='ally'?mats.coreBlue:mats.coreRed,glow=new T.MeshStandardMaterial({color,emissive:color,emissiveIntensity:1.5,roughness:.3,metalness:.4});glow.userData.owned=true;
if(c.layer===0){box(c.group,3.2,.55,3.2,0,.275,0,mats.dark);box(c.group,2.1,.45,2.1,0,.77,0,metal);box(c.group,.9,2.2,.8,0,2.05,0,mats.steel);box(c.group,1.5,.6,.9,0,2.8,0,metal);const orb=new T.Mesh(new T.OctahedronGeometry(.75),glow);orb.position.y=3.8;c.group.add(orb);c.orb=orb;const ring=new T.Mesh(new T.TorusGeometry(1.1,.045,6,40),metal);ring.position.y=3.8;ring.rotation.x=.3;c.group.add(ring);}
else if(c.layer===1){box(c.group,2.1,.35,2.1,0,.175,0,mats.dark);const orb=new T.Mesh(new T.OctahedronGeometry(.23),glow);orb.position.set(.35,.55,-.3);c.group.add(orb);c.orb=orb;box(c.group,.5,.3,.5,-.6,.3,.5,mats.steel);}
else{box(c.group,3.3,.4,3.3,0,.2,0,mats.dark);cylinder(c.group,1.2,1.5,.5,0,.65,0,metal,8);cylinder(c.group,.75,1,2.3,0,2,0,mats.steel,8);const orb=new T.Mesh(new T.IcosahedronGeometry(.7),glow);orb.position.y=3.4;c.group.add(orb);c.orb=orb;for(let i=0;i<4;i++){const a=i*Math.PI/2;const barrel=cylinder(c.group,.12,.17,1.8,Math.sin(a)*1.1,3.2,Math.cos(a)*1.1,metal);barrel.rotation.z=Math.cos(a)*.8;barrel.rotation.x=Math.sin(a)*.8;}}
c.group.traverse(o=>{if(o.isMesh)o.userData.core=c;});}
function showHero(){if(hero){actors.remove(hero.group);disposeGroup(hero.group);}const l=Math.max(...state.bag.gun,1);hero=soldier('ally',l);if(!state.bag.gun.length){hero.group.remove(hero.weapon);disposeGroup(hero.weapon);const blade=knifeModel(Math.max(...state.bag.knife,1));blade.position.set(.18,1.18,-.37);blade.scale.setScalar(.75);hero.group.add(blade);}hero.group.scale.setScalar(3.1);hero.group.position.set(11,0,13);hero.group.rotation.y=-.4;actors.add(hero.group);}
function buildViewWeapon(){disposeGroup(viewWeapon);const model=equipped.type==='knife'?knifeModel(equipped.level,true):gunModel(equipped.level,true);viewWeapon.add(model);viewWeapon.position.set(.32,-.30,-.85);viewWeapon.rotation.set(.015,-.06,0);model.scale.setScalar(.6);$('#equippedName').textContent=weaponInfo(equipped.type,equipped.level).name;$('#equippedLevel').textContent=`LV.${String(equipped.level).padStart(2,'0')}`;}
function ownedLoadouts(){const out=state.bag.gun.map(l=>({type:'gun',level:l}));const seen=new Set();return out.filter(i=>{const key=i.type+i.level;if(seen.has(key))return false;seen.add(key);return true;}).sort((a,b)=>b.level-a.level);}
function updateHub(){const th=theme();$('#stageName').innerHTML=`${String(Math.floor((state.stage-1)/5)%4+1).padStart(2,'0')} <span>${th.name}</span>`;$('#stageNum').textContent=String(state.stage).padStart(3,'0');$('#environmentLabel').textContent=`${th.name} · ${th.sub}`;$('#campaignProgress').style.width=`${state.stage/10}%`;$('#stageBrief').textContent=state.completed?'全部一千关已完成，可再次挑战终章。':state.stage===1?'初次部署：使用小刀与队友作战。通关解锁一级手枪。':state.stage===2?'推进前线：通关解锁一级地雷，可部署在敌人经过的位置。':state.stage===3?'突破防线：通关解锁一级手雷，下一关开启武器合成。':'行动目标：击破敌方三道核心。武器库已开放合成升级。';$('#income').textContent=fmt(income(state));const options=ownedLoadouts();const old=$('#loadout').value;$('#loadout').innerHTML=options.length?options.map(i=>`<option value="${i.type}:${i.level}">Lv.${i.level} ${weaponInfo(i.type,i.level).family}</option>`).join(''):'<option value="knife:1">一级小刀 · 近战兵</option>';if(options.some(i=>`${i.type}:${i.level}`===old))$('#loadout').value=old;$('#loadout').disabled=mode==='random';const top=options[0]??{type:'knife',level:Math.max(...state.bag.knife,1)};$('#heroWeapon').textContent=`Lv.${top.level} ${weaponInfo(top.type,top.level).family}`;$('#heroRole').textContent=`${weaponInfo(top.type,top.level).role} / 已就绪`;$('#mergeDot').style.display=state.stage>=4&&TYPES.some(t=>state.bag[t].some((l,i,a)=>l<500&&a.indexOf(l)!==i))?'block':'none';$('#dailyDot').style.display=daily(shanghaiDay())&&!state.claimed.includes(shanghaiDate())?'block':'none';updateWallet();}
function updateWallet(){for(const c of ['silver','gold','copper'])$('#'+c).textContent=fmt(state[c]);}
function gunSvg(type,level){if(type==='gun')return `<svg class="weapon-art" style="color:${weaponInfo(type,level).color}" viewBox="0 0 240 85"><path fill="currentColor" d="M28 29h74v-8h43v8h45v8h39v6h-43v10h-36l-6 21h-13l4-21h-18l-6 24H96l6-24H48L27 65H13V31h15z"/><path stroke="#14231e" stroke-width="3" d="M54 36h80m18 0h25M41 37v14m19-14v13m13-13v13"/>${level>=100?'<rect x="105" y="8" width="46" height="9" rx="4" fill="currentColor"/><path d="M115 17v8m25-8v8" stroke="currentColor" stroke-width="4"/>':''}</svg>`;if(type==='knife')return '<svg class="weapon-art" viewBox="0 0 240 85"><path fill="currentColor" d="m18 55 55-12 5 25-55 11zM80 33l10 39 8-3-3-15 91-22 35-27-132 33-2-8z"/><path stroke="#17231f" stroke-width="3" d="m31 54 4 17m9-20 4 17m10-20 4 17"/></svg>';return `<svg class="weapon-art" viewBox="0 0 240 85">${type==='mine'?'<ellipse cx="120" cy="54" rx="64" ry="20" fill="currentColor"/><path d="M59 53v13c0 23 122 23 122 0V53" fill="currentColor"/><ellipse cx="120" cy="50" rx="25" ry="8" fill="#23382b"/>':'<path d="M98 23h44l11 17v26l-14 13h-40L85 66V42z" fill="currentColor"/><path d="M105 23V10h32l22 31-7 5-23-25" fill="currentColor"/><path d="M89 48h61M89 62h61m-39-37v50m21-50v50" stroke="#23382b" stroke-width="3"/>'}</svg>`;}
function modal(tag,title,text,buttons){$('#modalTag').textContent=tag;$('#modalTitle').textContent=title;$('#modalText').innerHTML=text;$('#modalButtons').replaceChildren();for(const b of buttons){const el=document.createElement('button');el.textContent=b.label;if(b.primary)el.className='primary';el.onclick=()=>{hideModal();b.action();};$('#modalButtons').append(el);}$('#modalShade').hidden=false;}
function hideModal(){$('#modalShade').hidden=true;}
function selectTab(tab){if(inBattle)return;activeTab=tab;$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#panel').hidden=tab==='hub';if(tab==='hub')return;renderPanel();}
function renderPanel(){const titles={armory:['WEAPON ENGINEERING','武器库'],shop:['FIELD SUPPLY','补给商店'],daily:['WEEKLY SUPPLIES','每日领取'],defense:['CORE DEFENSE SYSTEM','核心防线']};if(!titles[activeTab])return;$('#panelEyebrow').textContent=titles[activeTab][0];$('#panelTitle').textContent=titles[activeTab][1];const body=$('#panelBody');
if(activeTab==='armory'){if(!unlocks(state).includes(armoryType))armoryType=unlocks(state).at(-1);const b=state.bag[armoryType],levels=[...new Set(b)].sort((a,b)=>b-a);body.innerHTML=`<div class="panel-summary"><span>合成两件<strong>同类型、同等级</strong>武器，获得更高一级装备。</span><span>${state.stage<4?'第 4 关开放合成':'合成奖励金币 · 最高 Lv.500'}</span></div><div class="pills">${TYPES.map(t=>`<button data-type="${t}" class="${t===armoryType?'selected':''}" ${!unlocks(state).includes(t)?'disabled':''}>${LABELS[t]} ${!unlocks(state).includes(t)?'· 未解锁':`· ${state.bag[t].length}`}</button>`).join('')}</div><div class="cards">${levels.map(l=>{const n=b.filter(v=>v===l).length,inf=weaponInfo(armoryType,l);return `<article class="card"><span class="level">LV.${String(l).padStart(3,'0')}</span><span class="count">持有 ×${n}</span>${gunSvg(armoryType,l)}<h3>${inf.name}</h3><p>伤害 ${fmt(inf.damage)}${armoryType==='gun'?`<br>持续收益 ${fmt(25*Math.pow(1.065,l-1))} 银币 / 秒`: '<br>战斗装备 / 可独立升级'}</p><button data-merge="${l}" ${state.stage<4||n<2||l>=500?'disabled':''}>${l>=500?'已达最高等级':`合成至 Lv.${l+1} · 需要 2 件`}</button><button data-buycopy="${l}">补充一件 · ${fmt(price(l))} 银币</button></article>`;}).join('')}</div>${!levels.length?'<div class="empty">尚未获得这类武器<br>继续通关即可解锁。</div>':''}<div class="notice">已解锁 ${state.high[armoryType]} / 500 级。枪械的外观和类型随等级变化：手枪、冲锋枪、突击步枪、狙击枪、巴雷特与科技枪。所有已持有枪械都会产出银币。</div>`;$$('[data-type]').forEach(b=>b.onclick=()=>{armoryType=b.dataset.type;renderPanel();});$$('[data-merge]').forEach(b=>b.onclick=()=>{const result=merge(state,armoryType,+b.dataset.merge);toast(result.message);if(result.ok){audio('merge');save();showHero();updateHub();renderPanel();}});$$('[data-buycopy]').forEach(b=>b.onclick=()=>purchase(armoryType,+b.dataset.buycopy,'silver'));}
if(activeTab==='shop'){if(!unlocks(state).includes(shopType))shopType='knife';const high=Math.max(1,state.high[shopType]);const levels=shopCurrency==='silver'?[...new Set([1,Math.max(1,high-1),high])].sort((a,b)=>a-b):[...new Set([Math.max(1,high),Math.min(500,high+1),Math.min(500,high+3)])];body.innerHTML=`<div class="panel-summary"><span>银币购买<strong>已解锁级段</strong>的武器。</span><span>金币可直接购入<strong>更高等级</strong>武器。</span></div><div class="pills"><button data-currency="silver" class="${shopCurrency==='silver'?'selected':''}">银币补给</button><button data-currency="gold" class="${shopCurrency==='gold'?'selected':''}">金币军备</button><button data-currency="skins" class="${shopCurrency==='skins'?'selected':''}">铜币皮肤</button></div>${shopCurrency!=='skins'?`<div class="pills">${unlocks(state).map(t=>`<button data-shoptype="${t}" class="${t===shopType?'selected':''}">${LABELS[t]}</button>`).join('')}</div><div class="cards">${levels.map(l=>{const inf=weaponInfo(shopType,l);return `<article class="card"><span class="level">LV.${String(l).padStart(3,'0')}</span>${gunSvg(shopType,l)}<h3>${inf.name}</h3><p>伤害 ${fmt(inf.damage)}<br>${l>high?'提前解锁新的级段':'已解锁 · 可重复购买'}</p><button data-shopbuy="${l}" ${shopCurrency==='gold'&&state.high.gun<2?'disabled':''}>${fmt(price(l,shopCurrency))} ${shopCurrency==='silver'?'银币':'金币'} · 购买</button></article>`;}).join('')}</div>`:`<div class="cards">${Object.entries(skins).map(([id,s])=>`<article class="card"><span class="level">${id.toUpperCase()}</span><div class="skin-swatch" style="--swatch:${s.color}"></div><h3>${s.name}</h3><p>角色迷彩涂装<br>外观皮肤 · 不改变伤害</p><button data-skin="${id}" ${state.skin===id?'disabled':''}>${state.skin===id?'已装备':state.skins.includes(id)?'装备皮肤':s.cost+' 铜币 · 解锁'}</button></article>`).join('')}</div>`}<div class="notice">${shopCurrency==='gold'?'金币来自武器合成升级和每周三领取；枪械达到二级后开放金币商店。':shopCurrency==='skins'?'铜币来自每周一领取。购买的皮肤会保留在本机存档中。':'枪械持续产出银币。一级枪当前设为每秒 25 银币，后续可按试玩体验调整。'}</div>`;$$('[data-currency]').forEach(b=>b.onclick=()=>{shopCurrency=b.dataset.currency;renderPanel();});$$('[data-shoptype]').forEach(b=>b.onclick=()=>{shopType=b.dataset.shoptype;renderPanel();});$$('[data-shopbuy]').forEach(b=>b.onclick=()=>purchase(shopType,+b.dataset.shopbuy,shopCurrency));$$('[data-skin]').forEach(b=>b.onclick=()=>{const id=b.dataset.skin;if(!state.skins.includes(id)){if(state.copper<skins[id].cost){toast('铜币不足，每周一可领取铜币');return;}state.copper-=skins[id].cost;state.skins.push(id);}state.skin=id;save();camoMat.map?.dispose();camoMat.map=camoTexture(skins[id].color);camoMat.userData.softwareColor=skins[id].color;camoMat.needsUpdate=true;toast('已装备 '+skins[id].name);updateWallet();renderPanel();});}
if(activeTab==='daily'){const day=shanghaiDay(),date=shanghaiDate(),r=daily(day),done=state.claimed.includes(date);body.innerHTML=`<div class="panel-summary"><span>每周补给 · 每个奖励日可领取一次</span><span>按北京时间结算 · ${date}</span></div><div class="daily-grid">${[1,2,3,4,5,6,0].map((d,i)=>{const a=daily(d);return `<article class="daily-card ${d===day?'today':''}"><span>星期${['一','二','三','四','五','六','日'][i]}</span><div class="daily-icon">${!a?'—':a.currency==='gold'?'◉':a.currency==='copper'?'◈':a.currency==='silver'?'◎':'⌁'}</div><strong>${!a?'无奖励':a.currency?`${a.amount} ${a.currency==='gold'?'金币':a.currency==='silver'?'银币':'铜币'}`:`${a.level} 级手枪`}</strong><small>${d===day?done?'今日已领取':'今天':'每周补给'}</small></article>`;}).join('')}</div><div class="claim-bar"><span>${done?'今日补给已入库，下个奖励日再来。':r?'今日奖励已就绪，点击领取。':'今天没有补给奖励，可继续战役积累资源。'}</span><button class="primary" id="claimDaily" ${!r||done?'disabled':''}>${done?'今日已领取':'领取今日奖励'}</button></div><div class="notice">奖励按星期固定，不要求连续签到。周六、周日送出的枪可直接使用；合成仍在第四关开放。</div>`;$('#claimDaily').onclick=()=>{const result=claim(state,shanghaiDate(),shanghaiDay());toast(result.message);if(result.ok){audio('merge');save();showHero();updateHub();renderPanel();}};}
if(activeTab==='defense'){const cost=coreCost();body.innerHTML=`<div class="panel-summary"><span>当前核心等级 <strong>Lv.${state.coreLevel}</strong></span><span>只有我方三道核心全部被摧毁，才会失败。</span></div><div class="defense-grid"><article class="defense-card"><small>DEFENSE / 01</small><div class="core-icon">⬡</div><h3>雕像核心</h3><p>第一道坚固防线。雕像被破坏后，隐藏的小核心显露，战斗继续。</p></article><article class="defense-card"><small>DEFENSE / 02</small><div class="core-icon">◇</div><h3>隐蔽小核心</h3><p>藏在雕像底座中的微小核心。靠近并仔细观察，才能发现它。</p></article><article class="defense-card"><small>DEFENSE / 03</small><div class="core-icon">✧</div><h3>激光核心</h3><p>最后一道防线，发射激光反击附近敌人。升级提高耐久和激光伤害。</p></article></div><div class="claim-bar"><span>升级会增强我方三道核心，最高 Lv.500。</span><button class="primary" id="upgradeCore" ${state.gold<cost||state.coreLevel>=500?'disabled':''}>${state.coreLevel>=500?'已满级':`升级核心 · ${fmt(cost)} 金币`}</button></div><div class="notice">敌方也设有三道核心；摧毁敌方最后一道即可通关。角色倒下后会重新加入战斗，不设置时间限制。</div>`;$('#upgradeCore').onclick=()=>{if(state.gold<coreCost()||state.coreLevel>=500)return;state.gold-=coreCost();state.coreLevel++;save();toast('核心已升级至 Lv.'+state.coreLevel);audio('merge');updateWallet();renderPanel();};}}
function coreCost(){return Math.ceil(30*Math.pow(1.055,state.coreLevel-1));}
function purchase(type,l,c){const result=buy(state,type,l,c);toast(result.message);if(result.ok){audio('buy');save();updateHub();showHero();renderPanel();}}
let audioContext;
function audio(kind){try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.connect(gain).connect(audioContext.destination);const now=audioContext.currentTime;osc.type=kind==='shot'?'sawtooth':kind==='blast'?'triangle':'sine';const f=kind==='shot'?115:kind==='blast'?65:kind==='merge'?550:350;osc.frequency.setValueAtTime(f,now);osc.frequency.exponentialRampToValueAtTime(kind==='merge'?950:35,now+.13);gain.gain.setValueAtTime(kind==='shot'?.035:.06,now);gain.gain.exponentialRampToValueAtTime(.001,now+.16);osc.start(now);osc.stop(now+.17);}catch{}}
function pickLoadout(){const list=ownedLoadouts();if(!list.length)return {type:'knife',level:Math.max(...state.bag.knife,1)};if(mode==='random')return list[Math.floor(Math.random()*list.length)];const [type,l]=$('#loadout').value.split(':');return list.find(i=>i.type===type&&i.level===+l)??list[0];}
function resetBattle(){bots.forEach(b=>disposeGroup(b.group));cores.forEach(c=>disposeGroup(c.group));if(hero)disposeGroup(hero.group);hero=null;actors.clear();effects.traverse(o=>{o.geometry?.dispose();if(o.material&&!o.material.userData.shared){o.material.dispose();}});effects.clear();tracers=[];bursts=[];mines=[];bots=[];cores=[];keys={};joy={x:0,y:0};mouseDown=false;prone=false;playerHP=100;respawnTime=0;battleKills=0;jumpHeight=0;velocityY=0;shootTimer=0;grenadeTimer=0;mineTimer=0;clock=0;}
function startBattle(){audio('buy');resetBattle();buildWorld();battleStage=state.stage;equipped=pickLoadout();cores=[makeCore('ally',state.coreLevel,battleStage),makeCore('enemy',1,battleStage)];const allyCount=3+Math.floor(Math.random()*3),enemyCount=4+Math.min(6,Math.floor((battleStage-1)/30))+Math.floor(Math.random()*2);for(let i=0;i<allyCount+enemyCount;i++){const team=i<allyCount?'ally':'enemy',b=soldier(team,team==='ally'?Math.max(...state.bag.gun,1):Math.min(500,1+Math.floor(battleStage/3)));b.maxHP=team==='ally'?95+battleStage*2:60+battleStage*3;b.hp=b.maxHP;respawnBot(b,i);actors.add(b.group);bots.push(b);b.hit.forEach(m=>m.userData.bot=b);}
playerPos.set(0,0,43);yaw=0;pitch=0;inBattle=true;paused=false;ended=false;selectTab('hub');$('#panel').hidden=true;document.body.classList.add('playing');$('#battle').hidden=false;$('#battleTitle').textContent=`第 ${battleStage} 关 · ${theme().name}`;$('#respawn').hidden=true;buildViewWeapon();viewWeapon.visible=true;updateBattleHUD();$('#proneButton').textContent='趴下';if(!matchMedia('(pointer:coarse)').matches&&innerWidth>600){try{renderer.domElement.requestPointerLock()?.catch(()=>{});}catch{}}toast(equipped.type==='knife'?'按住开火挥刀；靠近敌方核心进行攻击':'按住开火射击，拖动右侧或移动鼠标瞄准');}
function respawnBot(b,i=0){b.group.position.set((i%5-2)*3.5+(Math.random()-.5)*2,0,b.team==='ally'?42+Math.random()*5:-42-Math.random()*5);if(b.team==='ally'&&Math.abs(b.group.position.x)<4)b.group.position.x+=6;b.group.visible=true;b.dead=false;b.hp=b.maxHP??80;b.cooldown=Math.random();}
function blocked(x,z,r=.4){if(Math.abs(x)>46||Math.abs(z)>67)return true;return obstacles.some(o=>Math.abs(x-o.x)<o.w+r&&Math.abs(z-o.z)<o.d+r);}
function movePosition(pos,dx,dz){if(!blocked(pos.x+dx,pos.z))pos.x+=dx;if(!blocked(pos.x,pos.z+dz))pos.z+=dz;}
function lineOfSight(from,to){const d=to.clone().sub(from),length=d.length();d.normalize();const ray=new T.Raycaster(from,d,.2,length-.4);return !ray.intersectObjects(coverMeshes,false).length;}
function trace(from,to,color='#e9daa3',life=.12){const g=new T.BufferGeometry().setFromPoints([from,to]),m=new T.LineBasicMaterial({color,transparent:true,opacity:.9});const line=new T.Line(g,m);effects.add(line);tracers.push({obj:line,life,max:life});}
function burst(pos,color='#e9d48d',scale=1){const group=new T.Group();group.position.copy(pos);for(let i=0;i<7;i++){const p=new T.Mesh(new T.IcosahedronGeometry(.08*scale,0),new T.MeshBasicMaterial({color,transparent:true}));p.position.set((Math.random()-.5)*scale,(Math.random()-.2)*scale,(Math.random()-.5)*scale);p.userData.vel=new T.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5);group.add(p);}effects.add(group);bursts.push({group,life:.5,max:.5});}
function hurtBot(b,n){if(b.dead)return;b.hp-=n;if(b.hp<=0){b.dead=true;b.respawn=6;b.group.visible=false;burst(b.group.position.clone().add(new T.Vector3(0,1,0)),b.team==='enemy'?'#cfac7b':'#acb99d');if(b.team==='enemy'){battleKills++;state.kills++;}}}
function hurtPlayer(n){if(respawnTime>0||ended)return;playerHP=Math.max(0,playerHP-n);damageOpacity=.55;if(playerHP===0){respawnTime=4;viewWeapon.visible=false;mouseDown=false;} }
function hurtCore(c,n){if(c.dead||ended)return;const switched=damageCore(c,n,c.hps);if(switched){burst(c.group.position.clone().add(new T.Vector3(0,1.5,0)),c.team==='ally'?'#cce67c':'#efb17f',2);drawCore(c);if(c.dead)finishBattle(c.team==='enemy');else toast(`${c.team==='ally'?'我方':'敌方'}${c.layer===1?'雕像已破坏，寻找底座里的小核心':'小核心已破坏，激光核心启动'}`);} }
function coreTarget(c){return c.group.position.clone().add(new T.Vector3(c.layer===1?.35:0,c.layer===1?.55:c.layer===2?3.3:2.6,c.layer===1?-.3:0));}
function shoot(){if(paused||ended||respawnTime>0||shootTimer>0)return;const inf=weaponInfo(equipped.type,equipped.level);shootTimer=inf.rate;shotKick=equipped.type==='knife'?.23:.065;audio(equipped.type==='knife'?'buy':'shot');const origin=camera.getWorldPosition(new T.Vector3()),dir=camera.getWorldDirection(new T.Vector3());const ray=new T.Raycaster(origin,dir,0,inf.range);scene.updateMatrixWorld(true);const targets=[...coverMeshes];for(const b of bots)if(!b.dead)targets.push(...b.hit);for(const c of cores)if(!c.dead)c.group.traverse(o=>{if(o.isMesh)targets.push(o);});const hits=ray.intersectObjects(targets,false);const target=hits[0];let to=origin.clone().addScaledVector(dir,Math.min(inf.range,80));if(target){to=target.point;const b=target.object.userData.bot,c=target.object.userData.core;if(b?.team==='enemy'){hurtBot(b,inf.damage);hitOpacity=1;}else if(c?.team==='enemy'){hurtCore(c,inf.damage);hitOpacity=1;}burst(to,hitOpacity?'#cde6a5':'#d0c6a4',.5);}if(equipped.type!=='knife')trace(origin.clone().add(new T.Vector3(.12,-.12,0)),to,equipped.level>=420?'#75ffe0':'#f6e3ab');}
function explode(pos,damage){audio('blast');burst(pos.clone().add(new T.Vector3(0,.7,0)),'#ffd39a',3);for(const b of bots)if(b.team==='enemy'&&!b.dead&&b.group.position.distanceTo(pos)<8)hurtBot(b,damage);const c=cores[1];if(!c.dead&&c.group.position.distanceTo(pos)<8)hurtCore(c,damage*.85);}
function throwGrenade(){if(!inBattle||paused||ended||respawnTime>0)return;if(!state.bag.grenade.length){toast('第三关通关后解锁手雷');return;}if(grenadeTimer>0){toast('手雷补给中，请稍候');return;}grenadeTimer=7;const dir=camera.getWorldDirection(new T.Vector3());const pos=playerPos.clone().addScaledVector(new T.Vector3(dir.x,0,dir.z).normalize(),15);pos.y=0;explode(pos,weaponInfo('grenade',Math.max(...state.bag.grenade)).damage);}
function plantMine(){if(!inBattle||paused||ended||respawnTime>0)return;if(!state.bag.mine.length){toast('第二关通关后解锁地雷');return;}if(mineTimer>0){toast('地雷补给中，请稍候');return;}mineTimer=8;const pos=playerPos.clone();const mesh=cylinder(effects,.4,.5,.12,pos.x,.07,pos.z,material('#9ba768'),12);mines.push({mesh,pos,damage:weaponInfo('mine',Math.max(...state.bag.mine)).damage});toast('地雷已部署，敌人接近时引爆');}
function switchWeapon(){if(!inBattle||paused||respawnTime>0)return;if(equipped.type==='knife'){const list=ownedLoadouts();if(!list.length){toast('通关第一关后获得手枪');return;}equipped=mode==='random'?list[Math.floor(Math.random()*list.length)]:list.find(i=>`${i.type}:${i.level}`===$('#loadout').value)??list[0];}else equipped={type:'knife',level:Math.max(...state.bag.knife,1)};buildViewWeapon();}
function jump(){if(inBattle&&!paused&&jumpHeight===0&&!prone&&respawnTime===0)velocityY=5.7;}
function toggleProne(){if(!inBattle||paused||respawnTime>0)return;prone=!prone;$('#proneButton').textContent=prone?'站起':'趴下';}
function updateBots(dt){for(const b of bots){if(b.dead){b.respawn-=dt;if(b.respawn<=0)respawnBot(b,Math.floor(Math.random()*5));continue;}b.cooldown-=dt;const pos=b.group.position,enemyTeam=b.team==='ally'?'enemy':'ally';let target=null,dist=Infinity;for(const other of bots){if(other.team!==enemyTeam||other.dead)continue;const d=pos.distanceTo(other.group.position);if(d<dist){dist=d;target=other;}}if(b.team==='enemy'&&respawnTime<=0){const d=pos.distanceTo(playerPos);if(d<dist){dist=d;target='player';}}const theirCore=b.team==='ally'?cores[1]:cores[0];let targetPos;if(target&&dist<25)targetPos=target==='player'?playerPos.clone().add(new T.Vector3(0,prone?.55:1.45,0)):target.group.position.clone().add(new T.Vector3(0,1.2,0));else {target=theirCore;targetPos=coreTarget(theirCore);dist=pos.distanceTo(theirCore.group.position);}const dx=targetPos.x-pos.x,dz=targetPos.z-pos.z;b.group.rotation.y=Math.atan2(-dx,-dz);const attackRange=target===theirCore?21:18;if(dist>attackRange){const len=Math.hypot(dx,dz);const ox=pos.x,oz=pos.z;movePosition(pos,dx/len*b.speed*dt,dz/len*b.speed*dt);if(Math.abs(pos.x-ox)+Math.abs(pos.z-oz)<dt){movePosition(pos,Math.sin(clock+b.phase)*b.speed*dt*1.7,Math.cos(clock+b.phase)*b.speed*dt);}b.legL.rotation.x=Math.sin(clock*8+b.phase)*.45;b.legR.rotation.x=-b.legL.rotation.x;}else{b.legL.rotation.x=0;b.legR.rotation.x=0;if(b.cooldown<=0){b.cooldown=.65+Math.random()*.5;const from=pos.clone().add(new T.Vector3(0,1.3,0));if(lineOfSight(from,targetPos)){trace(from,targetPos,b.team==='ally'?'#d1e9a2':'#eec097');if(target==='player')hurtPlayer((4+battleStage*.12)*(prone?.65:1));else if(target===theirCore)hurtCore(theirCore,b.team==='ally'?8+battleStage*.3:5+battleStage*.18);else hurtBot(target,7+battleStage*.2);}}}}
for(const c of cores){if(c.dead||c.layer!==2)continue;c.cooldown-=dt;if(c.cooldown<=0){c.cooldown=1.5;const targets=bots.filter(b=>b.team!==c.team&&!b.dead&&b.group.position.distanceTo(c.group.position)<30);let target=targets.sort((a,b)=>a.group.position.distanceTo(c.group.position)-b.group.position.distanceTo(c.group.position))[0];if(c.team==='enemy'&&respawnTime<=0&&playerPos.distanceTo(c.group.position)<30&&(!target||playerPos.distanceTo(c.group.position)<target.group.position.distanceTo(c.group.position)))target='player';if(target){const from=coreTarget(c),to=target==='player'?playerPos.clone().add(new T.Vector3(0,1,0)):target.group.position.clone().add(new T.Vector3(0,1,0));if(lineOfSight(from,to)){trace(from,to,c.team==='ally'?'#a3ffd2':'#ff9972',.22);if(target==='player')hurtPlayer(16+c.level*5);else hurtBot(target,22+c.level*9);}}}}
}
function updateBattleHUD(){const [a,e]=cores;if(!a)return;for(const [c,id] of [[a,'ally'],[e,'enemy']]){$('#'+id+'Layers').innerHTML=[0,1,2].map(i=>`<i class="layer ${i<c.layer||c.dead?'dead':''}"></i>`).join('');$('#'+id+'HP').value=c.dead?0:c.hp/c.max;}$('#playerHP').value=playerHP;$('#healthText').textContent=Math.ceil(playerHP);const alive=bots.filter(b=>b.team==='ally'&&!b.dead).length;$('#squadInfo').textContent=`队友 ${alive} / ${bots.filter(b=>b.team==='ally').length} · 击倒 ${battleKills}`;$('#grenadeButton').disabled=!state.bag.grenade.length||grenadeTimer>0;$('#grenadeButton').innerHTML=`手雷 <small>${grenadeTimer>0?Math.ceil(grenadeTimer)+'s':'G'}</small>`;$('#mineButton').disabled=!state.bag.mine.length||mineTimer>0;$('#mineButton').innerHTML=`地雷 <small>${mineTimer>0?Math.ceil(mineTimer)+'s':'F'}</small>`;const d=Math.round(playerPos.distanceTo(e.group.position));$('#objectiveHint').textContent=e.layer===0?`向敌方雕像推进 · ${d}m`:e.layer===1?d<22?'在雕像底座寻找微小核心':'敌方底座里藏着小核心 · 靠近寻找':`摧毁激光核心 · ${d}m`;}
function finishBattle(win){if(ended)return;ended=true;paused=true;mouseDown=false;keys={};document.exitPointerLock?.();if(win){const result=completeStage(state,battleStage);save();const newText=result.type?`<br>新装备已解锁：<strong>一级${LABELS[result.type]}</strong>`:'';modal('MISSION COMPLETE',state.completed?'战役全部完成':'防线已突破',`第 ${battleStage} 关完成 · 击倒 ${battleKills} 名敌人。<br>获得 <strong>${fmt(result.reward??0)} 银币</strong>${newText}${state.stage===4?'<br><strong>武器合成功能现已开放。</strong>':''}`,[{label:'返回指挥台',action:returnHub},{label:state.completed?'重战终章':'进入下一关',primary:true,action:startBattle}]);}else modal('DEFENSE LOST','核心防线失守',`我方三道核心均已被摧毁。<br>武器和已获得的资源保留，可以调整装备后重试。`,[{label:'返回指挥台',action:returnHub},{label:'重新挑战',primary:true,action:startBattle}]);}
function returnHub(){inBattle=false;paused=false;ended=false;mouseDown=false;keys={};document.exitPointerLock?.();resetBattle();$('#battle').hidden=true;$('#respawn').hidden=true;document.body.classList.remove('playing');viewWeapon.visible=false;buildWorld();cores=[makeCore('ally',state.coreLevel,state.stage),makeCore('enemy',1,state.stage)];showHero();updateHub();selectTab('hub');}
function pauseBattle(){if(!inBattle||ended||paused)return;paused=true;mouseDown=false;keys={};joy={x:0,y:0};document.exitPointerLock?.();modal('OPERATION PAUSED','战斗已暂停','暂停期间，双方都不会移动或攻击。',[{label:'返回指挥台',action:returnHub},{label:'继续战斗',primary:true,action:()=>{paused=false;if(!matchMedia('(pointer:coarse)').matches&&innerWidth>600){try{renderer.domElement.requestPointerLock()?.catch(()=>{});}catch{}}}}]);}
function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-(animate.last??now))/1000,renderer instanceof SoftwareRenderer?.2:.05);animate.last=now;menuYaw+=dt;const earn=income(state)*dt;state.silver+=earn;if(now-lastSave>5000){save();lastSave=now;}if(Math.floor(now/400)!==animate.uiTick){animate.uiTick=Math.floor(now/400);updateWallet();if(shanghaiDate()!==lastDailyDate){lastDailyDate=shanghaiDate();updateHub();if(!inBattle&&activeTab==='daily')renderPanel();}if(inBattle)updateBattleHUD();}
if(inBattle){if(!paused&&!ended){clock+=dt;shootTimer=Math.max(0,shootTimer-dt);grenadeTimer=Math.max(0,grenadeTimer-dt);mineTimer=Math.max(0,mineTimer-dt);if(respawnTime>0){respawnTime-=dt;$('#respawn').hidden=false;$('#respawn').innerHTML=`${Math.ceil(respawnTime)} 秒后重新加入<small>核心还在，战斗就会继续</small>`;if(respawnTime<=0){respawnTime=0;playerPos.set((Math.random()-.5)*5,0,43);playerHP=100;prone=false;yaw=0;pitch=0;viewWeapon.visible=true;$('#respawn').hidden=true;$('#proneButton').textContent='趴下';}}else{let mx=(keys.KeyD?1:0)-(keys.KeyA?1:0)+joy.x,mz=(keys.KeyS?1:0)-(keys.KeyW?1:0)+joy.y;const length=Math.hypot(mx,mz);if(length>1){mx/=length;mz/=length;}const speed=(prone?2.2:keys.ShiftLeft?9.2:6.4)*dt;movePosition(playerPos,(Math.cos(yaw)*mx+Math.sin(yaw)*mz)*speed,(-Math.sin(yaw)*mx+Math.cos(yaw)*mz)*speed);velocityY-=16*dt;jumpHeight=Math.max(0,jumpHeight+velocityY*dt);if(jumpHeight===0)velocityY=0;camera.position.set(playerPos.x,(prone?.56:1.7)+jumpHeight,playerPos.z);camera.rotation.set(pitch,yaw,0);viewWeapon.position.set(.32,-.30+Math.sin(clock*9)*Math.min(length,1)*.012-shotKick*.3,-.85+shotKick);viewWeapon.rotation.z=equipped.type==='knife'?-shotKick*2:0;if(mouseDown)shoot();}
updateBots(dt);for(let i=mines.length-1;i>=0;i--){const m=mines[i];if(bots.some(b=>b.team==='enemy'&&!b.dead&&b.group.position.distanceTo(m.pos)<2.8)){explode(m.pos,m.damage);effects.remove(m.mesh);m.mesh.geometry.dispose();mines.splice(i,1);}}}}
else{camera.position.set(16+Math.sin(menuYaw*.12)*.6,6.1,23.5);camera.lookAt(-1,2.4,0);if(hero){hero.group.position.y=Math.sin(menuYaw*1.3)*.025;hero.group.rotation.y=-.4+Math.sin(menuYaw*.2)*.08;}}
for(const c of cores)if(c.orb&&!c.dead){c.orb.rotation.y+=dt*.7;c.orb.rotation.z+=dt*.15;}
shotKick*=Math.exp(-dt*16);damageOpacity*=Math.exp(-dt*4);hitOpacity*=Math.exp(-dt*8);$('#damageFlash').style.opacity=damageOpacity;$('#hitMarker').style.opacity=hitOpacity;
for(let i=tracers.length-1;i>=0;i--){const t=tracers[i];t.life-=dt;t.obj.material.opacity=Math.max(0,t.life/t.max);if(t.life<=0){effects.remove(t.obj);t.obj.geometry.dispose();t.obj.material.dispose();tracers.splice(i,1);}}for(let i=bursts.length-1;i>=0;i--){const b=bursts[i];b.life-=dt;b.group.children.forEach(p=>{p.position.addScaledVector(p.userData.vel,dt);p.material.opacity=Math.max(0,b.life/b.max);});if(b.life<=0){effects.remove(b.group);b.group.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});bursts.splice(i,1);}}
renderer.render(scene,camera);}

$('#deploy').onclick=startBattle;$('#randomMode').onclick=()=>{mode='random';$('#randomMode').classList.add('selected');$('#chooseMode').classList.remove('selected');$('#loadout').disabled=true;};$('#chooseMode').onclick=()=>{mode='choose';$('#chooseMode').classList.add('selected');$('#randomMode').classList.remove('selected');$('#loadout').disabled=false;};$$('#nav button').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));$('#closePanel').onclick=()=>selectTab('hub');$('#brand').onclick=()=>selectTab('hub');$('#pause').onclick=pauseBattle;$('#jumpButton').onclick=jump;$('#proneButton').onclick=toggleProne;$('#switchButton').onclick=switchWeapon;$('#grenadeButton').onclick=throwGrenade;$('#mineButton').onclick=plantMine;
renderer.domElement.addEventListener('pointerdown',e=>{if(!inBattle||paused||ended||e.pointerType==='touch')return;mouseDown=true;if(document.pointerLockElement!==renderer.domElement){try{renderer.domElement.requestPointerLock()?.catch(()=>{});}catch{}}});window.addEventListener('pointerup',e=>{if(e.pointerType!=='touch')mouseDown=false;});window.addEventListener('pointercancel',e=>{if(e.pointerType!=='touch')mouseDown=false;});window.addEventListener('mousemove',e=>{if(inBattle&&!paused&&document.pointerLockElement===renderer.domElement){yaw-=e.movementX*.0023;pitch=Math.max(-1.3,Math.min(1.3,pitch-e.movementY*.0023));}});document.addEventListener('pointerlockchange',()=>{if(inBattle&&!paused&&!ended&&!document.pointerLockElement&&!matchMedia('(pointer:coarse)').matches)pauseBattle();});
window.addEventListener('keydown',e=>{if(!inBattle||paused)return;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Space')jump();if(e.code==='KeyC')toggleProne();if(e.code==='KeyG')throwGrenade();if(e.code==='KeyF')plantMine();if(e.code==='Digit1'||e.code==='Digit2')switchWeapon();if(e.code==='Escape')pauseBattle();});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};mouseDown=false;joy={x:0,y:0};if(inBattle&&!paused)pauseBattle();save();});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(inBattle&&!paused)pauseBattle();save();}else if(!inBattle){updateHub();if(activeTab==='daily')renderPanel();}});
const joyEl=$('#joystick'),stick=$('#stick');function updateJoy(e){const r=joyEl.getBoundingClientRect(),cx=r.x+r.width/2,cy=r.y+r.height/2;let x=(e.clientX-cx)/(r.width*.32),y=(e.clientY-cy)/(r.height*.32);const l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}joy={x,y};stick.style.transform=`translate(${x*r.width*.28}px,${y*r.height*.28}px)`;}
joyEl.addEventListener('pointerdown',e=>{e.preventDefault();joystickPointer=e.pointerId;joyEl.setPointerCapture(e.pointerId);updateJoy(e);});joyEl.addEventListener('pointermove',e=>{if(e.pointerId===joystickPointer)updateJoy(e);});for(const event of ['pointerup','pointercancel'])joyEl.addEventListener(event,()=>{joystickPointer=null;joy={x:0,y:0};stick.style.transform='';});
const look=$('#lookZone');let lastLook={x:0,y:0};look.addEventListener('pointerdown',e=>{e.preventDefault();lookPointer=e.pointerId;lastLook={x:e.clientX,y:e.clientY};look.setPointerCapture(e.pointerId);});look.addEventListener('pointermove',e=>{if(e.pointerId!==lookPointer||paused)return;yaw-=(e.clientX-lastLook.x)*.005;pitch=Math.max(-1.3,Math.min(1.3,pitch-(e.clientY-lastLook.y)*.005));lastLook={x:e.clientX,y:e.clientY};});for(const event of ['pointerup','pointercancel'])look.addEventListener(event,()=>lookPointer=null);
$('#fireButton').addEventListener('pointerdown',e=>{e.preventDefault();firePointer=e.pointerId;mouseDown=true;$('#fireButton').setPointerCapture(e.pointerId);shoot();});for(const event of ['pointerup','pointercancel'])$('#fireButton').addEventListener(event,e=>{if(e.pointerId===firePointer){firePointer=null;mouseDown=false;}});
window.addEventListener('contextmenu',e=>{if(inBattle)e.preventDefault();});window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<600?1.5:1.8));});window.addEventListener('pagehide',save);
